.forum-section {
    width: 90%;
    margin: 0 auto;
    border: 1px solid var(--color-sf-border, rgb(var(--color-sf-outline-variant, 196, 199, 197)));
    border-radius: 8px;
    background: var(--color-sf-content-bg-color, rgb(var(--color-sf-surface, 255, 255, 255)));
    padding: 20px;
}

.forum-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--color-sf-border, rgb(var(--color-sf-outline-variant, 196, 199, 197)));
    margin-bottom: 20px;
}

.forum-icon {
    font-size: 18px;
}

.forum-title {
    font-size: 17px;
    font-weight: 700;
    color: var(--color-sf-content-text-color, rgb(var(--color-sf-on-surface, 28, 27, 31)));
}

.rte-container {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    margin-bottom: 28px;
}

.rte-container .comment-avatar {
    flex-shrink: 0;
    margin: 2px 0 0 2px;
}

.rte-input {
    flex: 1;
    min-width: 0;
}

.rte-input #editor {
    margin-bottom: 10px;
}

.button-group {
    display: flex;
    gap: 8px;
}

.button-group .e-btn {
    font-size: 14px;
}

.button-group .e-outline {
    border: 1px solid var(--color-sf-border-dark, rgb(var(--color-sf-outline-variant, 196, 199, 197)));
    background: transparent;
    color: var(--color-sf-content-text-color, rgb(var(--color-sf-on-surface, 28, 27, 31)));
}

.button-group .e-outline:hover {
    background: var(--color-sf-content-bg-color-hover, transparent);
    border-color: var(--color-sf-border-dark, rgb(var(--color-sf-outline, 121, 116, 126)));
}

.comments-container {
    border-top: 1px solid var(--color-sf-border, rgb(var(--color-sf-outline-variant, 196, 199, 197)));
    padding-top: 16px;
}

.comments-title {
    font-size: 15px;
    font-weight: 700;
    display: block;
    margin-bottom: 14px;
    color: var(--color-sf-content-text-color, rgb(var(--color-sf-on-surface, 28, 27, 31)));
}

.comment-avatar {
    width: 36px;
    height: 36px;
    min-width: 36px;
    max-width: 36px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
    margin: 2px;
}

/* ListView container styling - target through container ID */
#commentsList {
    margin: 0;
    padding: 0;
}

#commentsList .e-list-item {
    display: block;
    height: auto;
    padding: 0 0 16px 2px;
    margin: 0 0 16px 0;
    border: none;
    border-bottom: 1px solid var(--color-sf-border, rgb(var(--color-sf-outline-variant, 196, 199, 197)));
}

#commentsList .e-list-item:last-child {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

#commentsList .e-text-content {
    display: block;
}

.comment-item {
    display: flex;
    flex-wrap: nowrap;
    gap: 12px;
    align-items: flex-start;
    width: 100%;
}

.comment-body {
    flex: 1;
    min-width: 0;
    padding: 10px 40px 10px 14px;
    position: relative;
}

.comment-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
    flex-wrap: wrap;
}

.comment-author {
    font-weight: 700;
    color: var(--color-sf-content-text-color, rgb(var(--color-sf-on-surface, 28, 27, 31)));
    font-size: 13.5px;
}

.comment-time {
    font-size: 11.5px;
    color: var(--color-sf-content-text-color-alt2, rgb(var(--color-sf-on-surface-variant, 73, 69, 78)));
}

.comment-text {
    color: var(--color-sf-content-text-color, rgb(var(--color-sf-on-surface, 28, 27, 31)));
    line-height: 1.5;
    word-wrap: break-word;
    font-size: 13.5px;
}

.comment-actions {
    position: absolute;
    top: 8px;
    right: 8px;
    display: flex;
    gap: 2px;
}

.action-btn {
    cursor: pointer;
    color: var(--color-sf-icon-color, rgb(var(--color-sf-on-surface-variant, 73, 69, 78)));
}

.action-btn:hover {
    background: var(--color-sf-content-bg-color-hover, rgb(var(--color-sf-primary-container, 234, 221, 255))) !important;
    color: var(--color-sf-primary, rgb(var(--color-sf-primary, 103, 80, 164))) !important;
}

.delete-btn:hover {
    background: var(--color-sf-error-container, rgb(var(--color-sf-error-container, 249, 222, 220))) !important;
    color: var(--color-sf-error, rgb(var(--color-sf-error, 179, 38, 30))) !important;
}

.no-comments {
    color: var(--color-sf-content-text-color-alt2, rgb(var(--color-sf-on-surface-variant, 73, 69, 78)));
    font-size: 13px;
    padding: 10px 0;
}
